import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Agents / ACP","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guides/acp.md","filePath":"ja/guides/acp.md","lastUpdated":1792323081000}'),d={name:"ja/guides/acp.md"};function n(l,e,s,i,h,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="agents-acp" tabindex="-1">Agents / ACP <a class="header-anchor" href="#agents-acp" aria-label="Permalink to &quot;Agents / ACP&quot;">​</a></h1><p>Memoh は Bot を ACP 互換のコーディングエージェントに接続できます。ACP エージェントは外部のコーディングワークフローで、Bot のチャットワークスペースから作業しつつ、自分のセッションを通常の chat / discuss とは分けて保ちます。</p><p>組み込みの agent profile は <strong>Codex</strong> と <strong>Claude Code</strong> の 2 つです。これらは現時点でサポートされているセットアップ経路であって、今後接続できる ACP 互換エージェントがこれだけに限られるという意味ではありません。</p><p>ACP エージェントは Bot のコンテナワークスペース内で動くため、Bot はコンテナベースの Workspace バックエンドを使っている必要があります。</p><hr><h2 id="セットアップの流れ" tabindex="-1">セットアップの流れ <a class="header-anchor" href="#セットアップの流れ" aria-label="Permalink to &quot;セットアップの流れ&quot;">​</a></h2><ol><li>Bot の<strong>詳細ページ</strong>を開き、<strong>エージェント</strong> タブに移動します。</li><li>エージェントごとに 1 行が表示されます。右側のスイッチで有効化し、行をクリックすると設定が開きます。</li><li>setup モードを選び、求められるフィールドを入力します。</li><li>保存して、チャットのワークスペースから起動します。</li></ol><p>各行は 3 つの状態のいずれかを示します: <strong>Needs setup</strong>（有効化済みだが認証情報が不足）、<strong>Disabled</strong>、緑のドット（準備完了）。</p><h3 id="エージェントごとの-setup-モード" tabindex="-1">エージェントごとの Setup モード <a class="header-anchor" href="#エージェントごとの-setup-モード" aria-label="Permalink to &quot;エージェントごとの Setup モード&quot;">​</a></h3><table tabindex="0"><thead><tr><th>エージェント</th><th>API Key</th><th>OAuth</th><th>Self-managed</th></tr></thead><tbody><tr><td><strong>Codex</strong></td><td>✅</td><td>✅ ChatGPT ログイン（デバイスコード）</td><td>✅</td></tr><tr><td><strong>Claude Code</strong></td><td>✅</td><td>✅ <code>claude setup-token</code> で生成した token を貼り付け</td><td>✅</td></tr></tbody></table><p><strong>Self-managed</strong> は、あなたがワークスペース内で自分で管理している設定をそのまま使って、Memoh がエージェントを起動することを意味します。</p><h3 id="codex-のデバイスコード認証" tabindex="-1">Codex のデバイスコード認証 <a class="header-anchor" href="#codex-のデバイスコード認証" aria-label="Permalink to &quot;Codex のデバイスコード認証&quot;">​</a></h3><p>Codex の設定で <strong>Use Device Code</strong> をクリックすると、Memoh が検証用 URL とワンタイムコードを表示します。OpenAI のページであなたが承認すれば、認証は自動で完了します。</p><blockquote><p>ワンタイムコードは、表示された OpenAI の検証用 URL でだけ入力してください——デバイスコードはフィッシングに悪用されることがあります。</p></blockquote><h2 id="adapter-の自動更新" tabindex="-1">Adapter の自動更新 <a class="header-anchor" href="#adapter-の自動更新" aria-label="Permalink to &quot;Adapter の自動更新&quot;">​</a></h2><p>Codex と Claude Code の adapter は npm パッケージです。Memoh はサービスプロセスの起動後に（Bot ごとに）1 回だけ npm 上の最新バージョンを解決してそれを起動するため、adapter の修正は Memoh 自体をアップグレードしなくても手に入ります。解決や起動に失敗した場合は、次のサービス再起動まで、ワークスペースイメージに同梱されたバージョンにフォールバックします。</p><hr><h2 id="reasoning-effort" tabindex="-1">Reasoning Effort <a class="header-anchor" href="#reasoning-effort" aria-label="Permalink to &quot;Reasoning Effort&quot;">​</a></h2><p>エージェントが対応している場合、コンポーザーのモデルピッカーで <strong>Reasoning</strong> にホバーすると、セッションごとに推論の強さを選べます。</p><ul><li>選択肢（とその名前）は外部エージェント自身が宣言するもので、モデルを切り替えると変わることがあります。</li><li>未選択時のデフォルトは、Codex が <code>medium</code>、Claude Code が <code>high</code> です。</li><li>選択はセッションごとに独立していて、モデルの選択とは互いに影響しません。</li></ul><p>以前選んだ強さが使えなくなった場合、Memoh は黙って失敗する代わりに、エージェントの選択肢を更新してあなたに選び直してもらいます。</p><hr><h2 id="添付ファイル" tabindex="-1">添付ファイル <a class="header-anchor" href="#添付ファイル" aria-label="Permalink to &quot;添付ファイル&quot;">​</a></h2><p>ACP エージェントのセッションはメッセージの添付ファイルをサポートします:</p><ul><li><strong>画像</strong>: エージェントが画像入力のサポートを宣言していればネイティブに送信されます。非対応の場合でも、画像に参照できるワークスペースパスがあれば、自動的にファイル参照へフォールバックします。</li><li><strong>ファイル</strong>、長いテキストの貼り付け、引用／返信メッセージが運ぶ添付ファイルは、ワークスペースパスまたは公開 URL の形でエージェントに渡されます。</li><li>テキストなしで添付ファイルだけを送ることもできます。</li></ul><p>添付ファイルをエージェントに届けられないときは、黙って破棄するのではなく、チャット内で明確なエラーを報告します。</p><hr><h2 id="デフォルトエージェント" tabindex="-1">デフォルトエージェント <a class="header-anchor" href="#デフォルトエージェント" aria-label="Permalink to &quot;デフォルトエージェント&quot;">​</a></h2><p>Bot のインタラクション設定には <strong>デフォルトエージェント</strong> のドロップダウンがあります——Memoh 本体か、有効化済みで設定が完了している任意の ACP エージェントを選べます。影響するのはこれ以降に新しく作られる 1 対 1 のセッションだけで、既存のセッションとグループチャットの Discuss には影響しません。</p><hr><h2 id="acp-エージェントセッション" tabindex="-1">ACP エージェントセッション <a class="header-anchor" href="#acp-エージェントセッション" aria-label="Permalink to &quot;ACP エージェントセッション&quot;">​</a></h2><p>ACP の作業には <code>acp_agent</code> セッションタイプが使われます。これらのセッションは Agents/ACP ワークフローが作成・管理するもので、通常の <code>/new chat</code> / <code>/new discuss</code> のルーティングは通りません。クライアントでは <code>acp_agent</code> で絞り込むことで、コーディング作業を日常の会話と分けて見られます。</p><hr><h2 id="関連ページ" tabindex="-1">関連ページ <a class="header-anchor" href="#関連ページ" aria-label="Permalink to &quot;関連ページ&quot;">​</a></h2><ul><li><a href="./working-with-bots.html">Bot</a></li><li><a href="./sessions.html">セッション</a></li><li><a href="./files.html">ファイル</a></li><li><a href="./../integrations/providers/llm.html">モデルプロバイダーとモデル</a></li></ul>',35)])])}const g=a(d,[["render",n]]);export{u as __pageData,g as default};
